-- 261: UI redesign for about-us / privacy-policy / payment-methods. Wraps the
--      existing content (via CONCAT, copy untouched) in a branded hero + styled
--      .tcd document container. Idempotent (guarded on tcd-hero). Also fixes two
--      pre-existing broken-HTML typos.

UPDATE cms_page SET content = CONCAT(, content, 0x3c2f6469763e) WHERE identifier = 'about-us.html' AND content NOT LIKE '%tcd-hero%';

UPDATE cms_page SET content = CONCAT(, content, 0x3c2f6469763e) WHERE identifier = 'privacy-policy.html' AND content NOT LIKE '%tcd-hero%';

UPDATE cms_page SET content = CONCAT(, content, 0x3c2f6469763e) WHERE identifier = 'payment-methods.html' AND content NOT LIKE '%tcd-hero%';

